<script>
/**
 * Folder picker used to move one or several files/folders.
 *
 * Browsing happens with absolute paths (the same convention used by the file
 * explorer for `list` / `rename`), so the destination can be handed over to
 * `api.files.move()` unchanged. Breadcrumbs are displayed relative to
 * `rootPath` to stay readable.
 */
export default {
  name: 'MoveDialog',
  props: {
    isVisible: {
      type: Boolean,
      default: false
    },
    // Paths of the selected entries (project relative or absolute)
    sources: {
      type: Array,
      default: () => []
    },
    // Folder to start browsing from
    startPath: {
      type: String,
      default: ''
    },
    // Project root, used for the breadcrumbs and as browsing limit
    rootPath: {
      type: String,
      default: ''
    }
  },
  emits: ['move', 'cancel'],
  data() {
    return {
      browsePath: '',
      entries: [],
      loading: false,
      error: null
    }
  },
  computed: {
    $api() {
      return this.$project.$api
    },
    normalizeRoot() {
      return (this.rootPath || '').replace(/\/+$/, '') || '/'
    },
    isRoot() {
      return this.browsePath === this.normalizeRoot
    },
    // Browsed folder expressed relative to the project root
    relativeBrowsedPath() {
      const root = this.normalizeRoot
      const browse = this.browsePath || root
      if (browse === root) return ''
      if (browse.startsWith(`${root}/`)) return browse.substring(root.length + 1)
      return browse.replace(/^\//, '')
    },
    displayPath() {
      return this.relativeBrowsedPath ? `/${this.relativeBrowsedPath}` : '/'
    },
    breadcrumbParts() {
      const relativePath = this.relativeBrowsedPath
      if (!relativePath) return []
      const parts = relativePath.split('/').filter(Boolean)
      return parts.map((name, ix) => ({
        name,
        path: `${this.normalizeRoot}/${parts.slice(0, ix + 1).join('/')}`
      }))
    },
    // Folders already being moved are not valid destinations
    folders() {
      const moving = new Set(this.sources)
      return this.entries
        .filter(entry => entry.is_dir)
        .map(entry => ({
          name: entry.name,
          path: this.joinPath(this.browsePath, entry.name)
        }))
        .filter(folder => !moving.has(folder.path))
        .sort((a, b) => a.name.localeCompare(b.name))
    },
    // Moving a folder into itself (or into one of its descendants) is not allowed
    invalidTarget() {
      return this.sources.some(source =>
        this.browsePath === source || this.browsePath.startsWith(`${source}/`)
      )
    }
  },
  watch: {
    isVisible: {
      immediate: true,
      handler(visible) {
        if (visible) this.reset()
      }
    }
  },
  methods: {
    joinPath(base, name) {
      const prefix = base === '/' ? '' : base
      return `${prefix}/${name}`.replace(/\/{2,}/g, '/')
    },
    baseName(path) {
      return (path || '').split('/').filter(Boolean).pop() || path
    },
    sourceBadgeIcon(source) {
      // Files have an extension in the last segment, folders do not
      return this.baseName(source)?.includes('.')
        ? 'fa-regular fa-file'
        : 'fa-solid fa-folder'
    },
    reset() {
      this.error = null
      const root = this.normalizeRoot
      const start = this.startPath && this.startPath !== '.' ? this.startPath : root
      this.browsePath = start.startsWith(root) ? start : root
      this.loadFolders(this.browsePath)
    },
    async loadFolders(path) {
      this.loading = true
      this.error = null
      try {
        const response = await this.$api.files.list(path)
        this.entries = response.files || []
      } catch (ex) {
        console.error('Error listing folders', ex)
        this.error = `Could not list "${path}"`
        this.entries = []
      } finally {
        this.loading = false
      }
    },
    browseTo(path) {
      this.browsePath = path || this.normalizeRoot
      this.loadFolders(this.browsePath)
    },
    goUp() {
      if (this.isRoot) return
      const root = this.normalizeRoot
      const parent = this.browsePath.substring(0, this.browsePath.lastIndexOf('/')) || root
      this.browseTo(parent.startsWith(root) ? parent : root)
    },
    confirm() {
      if (this.loading || this.invalidTarget) return
      this.$emit('move', this.browsePath)
    }
  }
}
</script>
