        <i class="fa-solid fa-ban"></i>
        <span class="text-sm">A folder cannot be moved inside itself.</span>
      </div>

      <!-- Actions -->
      <div class="modal-action">
        <button class="btn btn-ghost" @click="$emit('cancel')">Cancel</button>
        <button
          class="btn btn-primary"
